// src/App.js
import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation, useNavigate } from "react-router-dom";

import LoginForm from "./LoginForm";
import RegisterForm from "./RegisterForm";
import DepositForm from "./DepositForm";
import WithdrawForm from "./WithdrawForm";
import Home from "./Home";
import AdminDepositRequests from "./AdminDepositRequests";
import AdminWithdrawRequests from "./AdminWithdrawRequests";
import UserHistory from "./UserHistory";
import AdminUserHistory from "./AdminUserHistory";
import Match from "./components/Match";
import LudoBoard from "./components/LudoBoard";

// ✅ Wrapper to read state from navigation
function LudoBoardWrapper() {
  const location = useLocation();
  const { gameId, playerId } = location.state || {};

  if (!gameId || !playerId) {
    return <div className="text-center mt-12 text-red-600 font-semibold">❌ Game ID বা Player ID পাওয়া যায়নি।</div>;
  }

  return <LudoBoard gameId={gameId} playerId={playerId} />;
}

function App() {
  const [token, setToken] = useState(null);
  const [email, setEmail] = useState("");
  const [role, setRole] = useState(null);
  const [showRegister, setShowRegister] = useState(false);

  useEffect(() => {
    const savedToken = localStorage.getItem("authToken");
    if (savedToken) setToken(savedToken);
  }, []);

  useEffect(() => {
    const fetchUserInfo = async () => {
      if (!token) return;

      try {
        const res = await fetch("http://localhost:8080/api/user/profile", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });

        if (!res.ok) throw new Error("Failed to fetch user profile");

        const user = await res.json();
        setEmail(user.email || "");
        setRole(user.role || "");
      } catch (err) {
        console.error("User profile fetch error:", err);
        handleLogout();
      }
    };

    fetchUserInfo();
  }, [token]);

  const handleLogin = (token) => {
    localStorage.setItem("authToken", token);
    setToken(token);
  };

  const handleLogout = () => {
    localStorage.removeItem("authToken");
    setToken(null);
    setEmail("");
    setRole(null);
  };

  const handleRegisterSuccess = () => {
    setShowRegister(false);
  };

  const isAdmin = (role || "").toLowerCase() === "admin";

  // Show login or register
  if (!token) {
    return showRegister ? (
      <RegisterForm
        onRegisterSuccess={handleRegisterSuccess}
        goToLogin={() => setShowRegister(false)}
      />
    ) : (
      <LoginForm
        onLogin={handleLogin}
        onRegisterClick={() => setShowRegister(true)}
      />
    );
  }

  if (role === null) {
    return <p className="p-5">লোড হচ্ছে...</p>;
  }

  return (
    <Router>
      <Routes>
        <Route
          path="/"
          element={
            <Home
              token={token}
              email={email}
              onLogout={handleLogout}
            />
          }
        />
        <Route
          path="/deposit"
          element={<DepositForm token={token} onCancel={() => window.location.href = "/"} />}
        />
        <Route
          path="/withdraw"
          element={<WithdrawForm token={token} onCancel={() => window.location.href = "/"} />}
        />
        <Route
          path="/admin-deposits"
          element={isAdmin ? <AdminDepositRequests onCancel={() => window.location.href = "/"} /> : <Navigate to="/" />}
        />
        <Route
          path="/admin-withdraws"
          element={isAdmin ? <AdminWithdrawRequests onCancel={() => window.location.href = "/"} /> : <Navigate to="/" />}
        />
        <Route
          path="/user-history"
          element={<UserHistory onCancel={() => window.location.href = "/"} />}
        />
        <Route
          path="/admin-user-history"
          element={isAdmin ? <AdminUserHistory onCancel={() => window.location.href = "/"} /> : <Navigate to="/" />}
        />
        <Route
          path="/match"
          element={
            <Match
              userEmail={email}
              onGameStart={({ gameId, playerId }) => {
                // ✅ Navigate to /game with state
                window.history.pushState({}, "", "/game");
                window.location.href = "/game";
                localStorage.setItem("ludo-game-id", gameId);
                localStorage.setItem("ludo-player-id", playerId);
              }}
            />
          }
        />
        <Route
          path="/game"
          element={
            <LudoBoard
              gameId={parseInt(localStorage.getItem("ludo-game-id"))}
              playerId={parseInt(localStorage.getItem("ludo-player-id"))}
            />
          }
        />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </Router>
  );
}

export default App;
